$ErrorActionPreference = 'Stop'

function Split-List {
  param([string]$Text)
  if ([string]::IsNullOrWhiteSpace($Text)) { return @() }
  return $Text -split '\|' | ForEach-Object { $_.Trim() } | Where-Object { $_ -ne '' }
}

function To-Li {
  param([string[]]$Items)
  return ($Items | ForEach-Object { "<li>$_</li>" }) -join "`n"
}

function Build-Content {
  param([pscustomobject]$a)

  $before = To-Li (Split-List $a.Before)
  $steps = To-Li (Split-List $a.Steps)
  $deps = To-Li (Split-List $a.Dependencies)
  $access = To-Li (Split-List $a.Access)
  $edges = To-Li (Split-List $a.EdgeCases)
  $done = To-Li (Split-List $a.DoneRight)

  return @"
<h1>$($a.Title)</h1>
<p>$($a.Intro)</p>
<p>This article is written for real YouthSports workflows, not generic software steps.</p>

<h2>Before you start</h2>
<ul>
$before
</ul>

<h2>Step-by-step workflow</h2>
<ol>
$steps
</ol>

<h2>What controls this workflow</h2>
<ul>
$deps
</ul>

<h2>Access and visibility rules</h2>
<ul>
$access
</ul>

<h2>Common edge cases and fast fixes</h2>
<ul>
$edges
</ul>

<h2>You are done when</h2>
<ul>
$done
</ul>

<p>YouthSports is designed to keep family logistics clear, fast, and reliable across the season.</p>
"@
}

$date = Get-Date -Format 'yyyy-MM-dd HH:mm:ss'

$articles = @(
  [pscustomobject]@{ Title='Join a Team with an Invite Code'; Slug='join-a-team-with-an-invite-code'; Section='Getting Started'; Tags='guardians,teams,invite-codes,athletes,seasons,rosters,join'; Excerpt='Use an invite code to link your athlete to the right team.'; Intro='Invite code join is the fastest path from onboarding to active roster placement.'; Before='Get an active code from coach or admin.|Sign in, or be ready to sign in and return.|Make sure athlete profile exists in My Athletes.'; Steps='Open /portal/join and enter code.|If prompted, sign in or sign up and continue.|Review team and choose athlete and season.|Submit join request.|Open My Athletes and confirm team context appears.'; Dependencies='Code must be valid and active.|Season must be available.|Duplicate membership blocks creation.|Capacity checks can block completion.'; Access='Route is public, submit requires authentication.|Flow is guardian focused because child selection is required.|Feature visibility still depends on entitlement.'; EdgeCases='Invalid code: request a fresh code.|Too many attempts: wait and retry once.|No child shown: create athlete first.|Already member: ask staff to resolve membership state.'; DoneRight='Athlete has active membership in target team and season.|Calendar and team surfaces reflect the new context.|No unresolved join errors remain.' },
