  [pscustomobject]@{ Title='Request Attachment to an Existing Athlete Profile'; Slug='request-attachment-to-an-existing-athlete-profile'; Section='Getting Started'; Tags='guardians,athletes,attachment,approvals,rosters,organizations'; Excerpt='Attach to an existing athlete profile without creating duplicates.'; Intro='Attachment requests protect roster quality while adding the right guardian access.'; Before='Know athlete name as stored in org.|Choose correct organization if you have multiple.|Use at least two search characters.'; Steps='Open /portal/athletes/request-attachment.|Select organization and search athlete.|Review result details.|Submit request.|Track pending, approved, denied, or expired status.|Resubmit only when denied or expired.'; Dependencies='Parent role in selected org is required.|Approval is admin controlled.|Request state is tracked per athlete.|Expired requests can be resubmitted.'; Access='Route is parent only.|Search scope is limited to attachable athletes.|Only approved requests grant direct access.'; EdgeCases='No match: broaden search term.|Pending exists: wait for review.|Denied: resolve reason then resubmit.|Approved already: no new request required.'; DoneRight='Attachment is approved or clearly pending.|Athlete appears in your My Athletes view.|No duplicate profile was created.' },
