  [pscustomobject]@{ Title='Make Partial Payments Without Validation Errors'; Slug='make-partial-payments-without-validation-errors'; Section='Payments'; Tags='payments,partial-payments,billing,balances,fees,guardians'; Excerpt='Pay part of a fee while staying inside policy limits.'; Intro='Partial payment is supported when both org policy and fee settings allow it.'; Before='Find a fee with Pay Partial action.|Review minimum and remaining amount.|Enter exact amount you plan to pay now.'; Steps='Open Pay Partial from eligible fee card.|Read total, paid, and remaining values.|Enter amount between minimum and remaining.|Submit to partial checkout.|Complete payment and verify remaining balance.'; Dependencies='Org policy must allow partial payments.|Fee must allow partial payment.|Minimum is enforced at ten percent of total fee.|Amount cannot exceed remaining balance.'; Access='Partial button only appears when policy and fee flags align.|Payment entitlement still required.|Validation runs before checkout session starts.'; EdgeCases='No partial button: policy or fee flag disabled.|Amount too low: increase to minimum.|Amount too high: reduce to remaining balance.|Checkout error: retry once then contact billing.'; DoneRight='Partial payment posts successfully.|Remaining balance is reduced accurately.|Assignment status remains consistent.' },
