  [pscustomobject]@{ Title='RSVP Correctly for General and Athlete-Specific Events'; Slug='rsvp-correctly-for-general-and-athlete-specific-events'; Section='Events and Calendar'; Tags='calendar,rsvp,athletes,attendance,events,guardians'; Excerpt='Respond once or per athlete based on event RSVP mode.'; Intro='Different events require different RSVP behavior, and YouthSports supports both modes.'; Before='Open event detail or modal.|Confirm RSVP is enabled.|Check whether mode is general or athlete-specific.'; Steps='Open RSVP area.|Use general RSVP for family-level response.|Use athlete-specific RSVP for per-child response.|Wait for save state.|Reopen event to verify persisted values.'; Dependencies='RSVP mode is event-configured by staff.|Canceled events disable RSVP updates.|Optimistic updates reconcile with server result.|Past-event windows may hide response controls.'; Access='RSVP actions require authenticated role context.|Athlete-specific actions require visible child profiles.|Disabled RSVP events show no controls.'; EdgeCases='Save failed: retry once.|Wrong child status: edit that athlete row.|No RSVP controls: disabled or canceled event.|Past lock: responses intentionally unavailable.'; DoneRight='Coach sees intended attendance signal.|Each child status is correct where needed.|No unresolved RSVP error remains.' },
