  [pscustomobject]@{ Title='Use Secure Ticket Access Links at the Gate'; Slug='use-secure-ticket-access-links-at-the-gate'; Section='Tickets and Entry'; Tags='tickets,access-links,qr,entry-code,gate,mobile'; Excerpt='Open secure access links and use entry code fallback if needed.'; Intro='Ticket access links are optimized for gate speed with a QR token and entry code backup.'; Before='Open full token URL exactly as delivered.|Increase brightness before scan.|Keep phone charged and unlocked.'; Steps='Open /portal/tickets/access?t=...|Wait for ticket and QR load.|Present QR to scanner.|If needed, provide manual entry code.|Keep page active through gate entry.'; Dependencies='Token must be valid and unexpired.|Wake lock may be requested for screen stability.|Entry code maps to specific ticket.|Event data is loaded from token payload.'; Access='No full portal login needed with valid token.|Invalid token shows explicit error state.|Access scope is limited to token-linked ticket data.'; EdgeCases='Expired link: request fresh access link.|Missing token: reopen exact URL.|Weak signal: preload before arrival.|Scan failure: switch to entry code immediately.'; DoneRight='QR or entry code works at gate.|You enter without reauthentication.|Ticket metadata matches event and type.' },
