$rows = for ($i = 0; $i -lt $articles.Count; $i++) {
  $a = $articles[$i]
  [pscustomobject]@{
    ID = ''
    Title = $a.Title
    Content = (Build-Content -a $a)
    Excerpt = $a.Excerpt
    Slug = $a.Slug
    Status = 'publish'
    Parent = ''
    Order = $i + 1
    Author = 'admin'
    Date = $date
    'Allow Comments' = 'closed'
    'Allow Pingbacks' = 'closed'
    Categories = "Help, Guardians, $($a.Section)"
    Tags = $a.Tags
    Section = $a.Section
    'Role Category' = 'Guardians'
  }
}

$outPath = Join-Path (Get-Location) 'help-center-guardian-import-20-posts.csv'
$rows | Export-Csv -Path $outPath -NoTypeInformation -Encoding UTF8

Write-Output "Wrote: $outPath"
Write-Output "Rows: $($rows.Count)"
